package com.cpf.batch.runtime; import com.cpf.batch.api.*; import java.time.Instant; import java.util.*;
public final class RuntimeIdentityFactory { private RuntimeIdentityFactory(){} public static RuntimeRegistration fromEnvironment(RuntimeRole role,String serviceId,int defaultPort){String id=env("CPF_INSTANCE_ID",serviceId+"-local-01");int port=Integer.parseInt(env("CPF_PORT",Integer.toString(defaultPort)));List<String> caps=Arrays.stream(env("CPF_CAPABILITIES",role.name()).split(",")).map(String::trim).filter(s->!s.isEmpty()).toList();return new RuntimeRegistration(role,serviceId,id,"BAT",env("CPF_WAS_ID",id),env("CPF_HOST_ALIAS","localhost"),env("CPF_ZONE","local"),env("CPF_POOL","default"),env("CPF_ARTIFACT_VERSION","dev"),env("CPF_GIT_SHA","UNKNOWN"),env("CPF_ARTIFACT_SHA256","UNKNOWN"),env("SPRING_PROFILES_ACTIVE","local"),caps,Map.of("health","http://127.0.0.1:"+port+"/actuator/health/readiness","base","http://127.0.0.1:"+port),env("CPF_CONFIG_VERSION","local"),env("CPF_SCHEMA_COMPATIBILITY","UNKNOWN"),"v1",Instant.now());} private static String env(String k,String d){String v=System.getenv(k);return v==null||v.isBlank()?d:v;} }
